    /// <summary>
    /// Required. Represents the text that will be transformed to speech.
    ///
    /// &lt;p>The text may be plain text, or it may embed SSML markup, phonemes and voice-control tags to
    /// shape how it is spoken. The sections below list every supported form with a copy-paste example.
    /// Which forms take effect depends on the pipeline (model) selected via
    /// &lt;code>RequestConfig.t2s_pipeline_id&lt;/code>; unsupported tags are stripped and the plain text is
    /// still spoken.&lt;/p>
    ///
    /// &lt;p>&lt;b>1. Plain text&lt;/b>&lt;/p>
    /// &lt;ul>
    ///   &lt;li>Simple text: &lt;pre>&lt;code>Hello, how are you?&lt;/code>&lt;/pre>&lt;/li>
    /// &lt;/ul>
    ///
    /// &lt;p>&lt;b>2. SSML &lt;code>&amp;lt;say-as&amp;gt;&lt;/code> tags (local vits / qwen3-tts and cloud providers)&lt;/b>&lt;/p>
    /// &lt;p>Rewrites the enclosed text into its spoken form (spelled out letters, digits, symbols, ...).
    /// Supported by the local normalization pipeline and forwarded to the cloud providers.&lt;/p>
    /// &lt;ul>
    ///   &lt;li>Phone: &lt;pre>&lt;code>&amp;lt;say-as interpret-as=&amp;quot;phone&amp;quot;&amp;gt;+12354321&amp;lt;/say-as&amp;gt;&lt;/code>&lt;/pre>&lt;/li>
    ///   &lt;li>Email: &lt;pre>&lt;code>&amp;lt;say-as interpret-as=&amp;quot;email&amp;quot;&amp;gt;voices@ondewo.com&amp;lt;/say-as&amp;gt;&lt;/code>&lt;/pre>&lt;/li>
    ///   &lt;li>URL: &lt;pre>&lt;code>&amp;lt;say-as interpret-as=&amp;quot;url&amp;quot;&amp;gt;ondewo.com/en/&amp;lt;/say-as&amp;gt;&lt;/code>&lt;/pre>&lt;/li>
    ///   &lt;li>Spell (spell out each character): &lt;pre>&lt;code>&amp;lt;say-as interpret-as=&amp;quot;spell&amp;quot;&amp;gt;AP732&amp;lt;/say-as&amp;gt;&lt;/code>&lt;/pre>&lt;/li>
    ///   &lt;li>Spell with names (e.g. &amp;quot;A like Anton&amp;quot;): &lt;pre>&lt;code>&amp;lt;say-as interpret-as=&amp;quot;spell-with-names&amp;quot;&amp;gt;AHO32&amp;lt;/say-as&amp;gt;&lt;/code>&lt;/pre>&lt;/li>
    ///   &lt;li>Callsigns short: &lt;pre>&lt;code>&amp;lt;say-as interpret-as=&amp;quot;callsign-short&amp;quot;&amp;gt;AUA439&amp;lt;/say-as&amp;gt;&lt;/code>&lt;/pre>&lt;/li>
    ///   &lt;li>Callsigns long: &lt;pre>&lt;code>&amp;lt;say-as interpret-as=&amp;quot;callsign-long&amp;quot;&amp;gt;AAL439&amp;lt;/say-as&amp;gt;&lt;/code>&lt;/pre>&lt;/li>
    /// &lt;/ul>
    ///
    /// &lt;p>&lt;b>3. Pauses / breaks&lt;/b>&lt;/p>
    /// &lt;ul>
    ///   &lt;li>Break tag (seconds): &lt;pre>&lt;code>I am going to take a 2 seconds break &amp;lt;break time=&amp;quot;2.0&amp;quot;/&amp;gt; done&lt;/code>&lt;/pre>&lt;/li>
    ///   &lt;li>Break tag (milliseconds, cloud providers): &lt;pre>&lt;code>please wait &amp;lt;break time=&amp;quot;500ms&amp;quot;/&amp;gt; done&lt;/code>&lt;/pre>&lt;/li>
